import math

def _render(cx, cy, a, b, th, amp):
    ct, st = math.cos(th), math.sin(th)
    out = []
    for i in range(16):
        for j in range(16):
            dx, dy = j - cx, i - cy
            u = dx * ct + dy * st
            v = -dx * st + dy * ct
            rho = math.sqrt((u / a) ** 2 + (v / b) ** 2)
            grad = math.sqrt((u / (a * a)) ** 2 + (v / (b * b)) ** 2)
            t = 0.5 + (1.0 - rho) / max(grad, 1e-9)
            out.append(amp * max(0.0, min(1.0, t)))
    return out

def encode(img):
    def evaluate(q):
        base = _render(q[0], q[1], q[2], q[3], q[4], 1.0)
        dot = sum(x * y for x, y in zip(img, base))
        norm = sum(y * y for y in base)
        amp = max(0.4, min(1.1, dot / max(norm, 1e-12)))
        err = sum((x - amp * y) ** 2 for x, y in zip(img, base))
        return err, amp

    starts = []
    for cutoff in (0.10, 0.20, 0.30):
        weights = [max(0.0, x - cutoff) for x in img]
        mass = sum(weights)
        if mass < 1e-8:
            continue
        cx = sum((k % 16) * w for k, w in enumerate(weights)) / mass
        cy = sum((k // 16) * w for k, w in enumerate(weights)) / mass
        xx = yy = xy = 0.0
        for k, w in enumerate(weights):
            dx, dy = k % 16 - cx, k // 16 - cy
            xx += w * dx * dx
            yy += w * dy * dy
            xy += w * dx * dy
        xx, yy, xy = xx / mass, yy / mass, xy / mass
        disc = math.sqrt(max(0.0, (xx - yy) ** 2 + 4.0 * xy * xy))
        th = 0.5 * math.atan2(2.0 * xy, xx - yy)
        a = max(1.3, min(4.8, 2.0 * math.sqrt(max(0.2, (xx + yy + disc) / 2.0))))
        b = max(1.3, min(4.8, 2.0 * math.sqrt(max(0.2, (xx + yy - disc) / 2.0))))
        starts.append([cx, cy, a, b, th])
        starts.append([cx, cy, b, a, th + math.pi / 2])

    if not starts:
        starts = [[7.5, 7.5, 2.8, 2.0, 0.0]]

    best_q, best_err, best_amp = None, float("inf"), 0.8
    bounds = [(0.0, 15.0), (0.0, 15.0), (1.3, 4.8),
              (1.3, 4.8), (-math.pi / 2, math.pi / 2)]

    for start in starts:
        q = start[:]
        q[4] = (q[4] + math.pi / 2) % math.pi - math.pi / 2
        err, amp = evaluate(q)
        steps = [0.45, 0.45, 0.40, 0.40, 0.18]

        # Greedy coordinate pattern search, with progressively finer steps.
        for _ in range(24):
            changed = True
            while changed:
                changed = False
                for k in range(5):
                    for sign in (-1.0, 1.0):
                        trial = q[:]
                        trial[k] += sign * steps[k]
                        lo, hi = bounds[k]
                        if k == 4:
                            trial[k] = (trial[k] + math.pi / 2) % math.pi - math.pi / 2
                        else:
                            trial[k] = max(lo, min(hi, trial[k]))
                        e, ap = evaluate(trial)
                        if e < err:
                            q, err, amp = trial, e, ap
                            changed = True
                            break
            steps = [s * 0.68 for s in steps]

        # A few coupled moves help escape coordinate-wise local minima.
        for _ in range(3):
            improved = False
            for k in range(5):
                for l in range(k + 1, 5):
                    for sk in (-1.0, 1.0):
                        for sl in (-1.0, 1.0):
                            trial = q[:]
                            trial[k] += sk * steps[k] * 2.0
                            trial[l] += sl * steps[l] * 2.0
                            if k == 4:
                                trial[k] = (trial[k] + math.pi / 2) % math.pi - math.pi / 2
                            else:
                                trial[k] = max(bounds[k][0], min(bounds[k][1], trial[k]))
                            if l == 4:
                                trial[l] = (trial[l] + math.pi / 2) % math.pi - math.pi / 2
                            else:
                                trial[l] = max(bounds[l][0], min(bounds[l][1], trial[l]))
                            e, ap = evaluate(trial)
                            if e < err:
                                q, err, amp = trial, e, ap
                                improved = True
            if not improved:
                break

        if err < best_err:
            best_q, best_err, best_amp = q, err, amp

    return best_q + [best_amp]

def decode(z):
    return _render(z[0], z[1], z[2], z[3], z[4], z[5])
